// A Simple Menger Sponge Style "4D" Raymarch for Shadertoy
//   - "iTime" is the shader built-in uniform time
//   - "iResolution" is the screen resolution
//   - This code uses a single fractal function that depends
//     on a parameter w, simulating a 4th coordinate dimension.

#ifdef GL_ES
precision mediump float;
#endif

// A pseudo-random function for shading.
float hash13(vec3 p) {
    p  = fract(p * 0.3183099 + vec3(0.1,0.2,0.3));
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

// "Distance" function for a Menger-like fractal extended with a w param
float mengerDist(vec3 pos, float wParam) {
    // We'll do an iterative approach, limiting iteration for performance
    float scale = 1.0;
    float dist  = 1e9;
    vec3 z      = pos;
    for(int i = 0; i < 5; i++){
        // replicate z in [-1..1] range with folds (like repeating)
        z = mod(z*3.0, 2.0) - 1.0;
        // "Remove" center region in each iteration (like Menger)
        float remove = max(abs(z.x), max(abs(z.y), abs(z.z))) - 0.5;
        dist = min(dist, remove / scale);
        scale *= 3.0;
    }
    // We add a 4D twist: shift dist by a small sinusoid of wParam
    dist += 0.02 * sin(3.0 * wParam + pos.x*4.0);
    return dist;
}

// Basic raymarch
vec4 castRay(vec3 ro, vec3 rd, float wParam) {
    float t = 0.0;
    float maxT = 30.0;
    for(int i=0; i<128; i++) {
        vec3 p = ro + rd * t;
        float d = mengerDist(p, wParam);
        if(d < 0.001 || t > maxT) break;
        t += d * 0.5;
    }
    if(t>maxT) {
        // background
        return vec4(0.0, 0.0, 0.0, 1.0);
    }
    // compute normal by sampling distance
    vec2 e = vec2(0.002, 0.0);
    vec3 p = ro + rd * t;
    float d = mengerDist(p, wParam);
    vec3 n = normalize(vec3(
        mengerDist(p+vec3(e.x,e.y,e.y), wParam) - d,
        mengerDist(p+vec3(e.y,e.x,e.y), wParam) - d,
        mengerDist(p+vec3(e.y,e.y,e.x), wParam) - d
    ));
    // simple shading
    float diffuse = dot(n, normalize(vec3(1.0, 0.6, 0.4))) * 0.5 + 0.5;
    float rim = pow(1.0 - dot(rd, n), 2.0);
    vec3 col = vec3(diffuse * (0.1 + 0.9*rim));
    // Fake some color variation
    col += 0.05 * hash13(floor(p*3.0)*1.23);
    return vec4(col, 1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized coords
    vec2 uv = (fragCoord - 0.5*iResolution.xy) / iResolution.y;
    // camera
    float t = iTime * 0.003;
    // rotate camera around Y
    float cs = cos(t), sn = sin(t);
    vec3 ro = vec3(4.5*cs, 1.2, 2.5*sn);
    vec3 ta = vec3(0.2, 0.0, 0.5);
    // build camera basis
    vec3 ww = normalize(ta - ro);
    vec3 uu = normalize(cross(ww, vec3(0.0,1.0,0.0)));
    vec3 vv = cross(uu, ww);
    // construct ray
    vec3 rd = normalize( uu*uv.x + vv*uv.y + ww );

    // "4D parameter" wParam = let's have it oscillate with time
    float wParam = 0.5 + 0.5*sin(iTime*0.9);

    // cast
    vec4 color = castRay(ro, rd, wParam);
    fragColor = color;
}
